/* Exact ROM decoding into existing caller scratch; no allocation or audio-path work. */
static const int32_t *fp_values(uint32_t k, int32_t *scratch, uint32_t capacity)
{
    uint32_t i;
    if (k >= N_FPRESETS) return 0;
    if (FPRESET_LIST[k].n > capacity) return 0;
    const uint8_t *base = FPRESET_LIST[k].base ? FPRESET_LIST[k].base : FPRESET_LIST[k].v;
    for (i = 0; i < FPRESET_LIST[k].n; i++) scratch[i] = fp_decode(base, i);
    for (i = 0; i < FPRESET_LIST[k].changes; i++) scratch[FPRESET_LIST[k].rows[i]] = fp_decode(FPRESET_LIST[k].v, i);
    return scratch;
}

